-- Database setup, generated by scripts/copy-setup-sql.sh on 2026-11-25. Safe to run again.

-- >>> 20261116000028_account_storage_fixes.sql (skipped automatically if already applied)
do $guard$ begin
  if to_regproc('public.delete_my_account') is null then
    execute $setup_20261116000028_account_storage_fixes$
-- Security and privacy fixes (audit of 2026-11-25).
-- 1. Storage: thumbnails of My pile only next to their full image, a ceiling in bytes per player for
--    every bucket, a ceiling on bug screenshots; players can read (list) and delete their own files.
-- 2. Rights nobody needs: TRUNCATE (it ignores RLS), TRIGGER, REFERENCES, and any write by visitors.
-- 3. Account deletion by the player: personal data and photos are erased; what is shared with others
--    (played games, finished tournaments, campaign journals) stays under "Deleted player".

-- ---------------------------------------------------------------------------------------------
-- 1. Storage
-- ---------------------------------------------------------------------------------------------
drop policy if exists "pile photos: owners upload in their folder" on storage.objects;
create policy "pile photos: owners upload in their folder" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'pile' and (storage.foldername(name))[1] = auth.uid()::text
              and not public.is_suspended(auth.uid())
              and (public.thumb_has_main(bucket_id, name)
                   or (name !~ '\.t\.(webp|jpg|png)$' and public.pile_photo_count() < 500)));

-- Everything I store, in bytes (the app's photos weigh about 175 kB: 600 of them fit in 150 MB).
create or replace function public.my_storage_bytes()
returns bigint
language sql
stable
security definer
set search_path = public, storage
as $$
  select coalesce(sum((o.metadata ->> 'size')::bigint), 0)::bigint
    from storage.objects o where o.owner = auth.uid()
$$;
create or replace function public.my_bug_shots()
returns int
language sql
stable
security definer
set search_path = public, storage
as $$
  select count(*)::int from storage.objects o where o.owner = auth.uid() and o.bucket_id = 'bug-reports'
$$;
revoke execute on function public.my_storage_bytes(), public.my_bug_shots() from public, anon;
grant execute on function public.my_storage_bytes(), public.my_bug_shots() to authenticated;

drop policy if exists "files: size per player" on storage.objects;
create policy "files: size per player" on storage.objects
  as restrictive
  for insert to authenticated
  with check (public.my_storage_bytes() < 150 * 1024 * 1024);

-- Closed reports lose their screenshots after 90 days (cleanup), which frees the places.
drop policy if exists "bug screenshots: number per player" on storage.objects;
create policy "bug screenshots: number per player" on storage.objects
  as restrictive
  for insert to authenticated
  with check (bucket_id <> 'bug-reports' or public.is_admin() or public.my_bug_shots() < 60);

-- The Storage API only deletes files the player can also read: public buckets had no read policy,
-- so removing a photo there could leave the file behind.
drop policy if exists "own files: owners read" on storage.objects;
create policy "own files: owners read" on storage.objects
  for select to authenticated
  using (owner = auth.uid());
drop policy if exists "own files: owners delete" on storage.objects;
create policy "own files: owners delete" on storage.objects
  for delete to authenticated
  using (owner = auth.uid());

-- Every file of mine, so that the app can remove them before the account is deleted.
create or replace function public.my_files()
returns table (bucket text, name text)
language sql
stable
security definer
set search_path = public, storage
as $$ select o.bucket_id, o.name from storage.objects o where o.owner = auth.uid() order by 1, 2 $$;
revoke execute on function public.my_files() from public, anon;
grant execute on function public.my_files() to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 2. Rights nobody needs
-- ---------------------------------------------------------------------------------------------
do $rights$
declare
  r record;
begin
  for r in select tablename from pg_tables where schemaname = 'public' loop
    execute format('revoke truncate, trigger, references on public.%I from anon, authenticated', r.tablename);
    execute format('revoke insert, update, delete on public.%I from anon', r.tablename);
  end loop;
end $rights$;
-- Tables created later start without them too.
alter default privileges in schema public revoke truncate, trigger, references on tables from anon, authenticated;
alter default privileges in schema public revoke insert, update, delete on tables from anon;

-- Internal helper (pairings): it listed the players of any tournament, drafts included.
revoke execute on function public.tournament_players(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 3. Account deletion
-- ---------------------------------------------------------------------------------------------
alter table public.profiles add column if not exists deleted_at timestamptz;

create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public, auth, storage
as $$
declare
  me uuid := auth.uid();
  my_name text;
  x record;
  heir uuid;
begin
  if me is null then
    raise exception 'not_authenticated';
  end if;
  select display_name into my_name from public.profiles where id = me and deleted_at is null for update;
  if not found then
    raise exception 'not_found';
  end if;
  if public.is_admin() then
    raise exception 'admin_account';
  end if;
  -- The app asks for the password again just before; a session left open somewhere is not enough.
  if not exists (select 1 from auth.users u where u.id = me and u.last_sign_in_at > now() - interval '15 minutes') then
    raise exception 'recent_sign_in';
  end if;
  -- Players are waiting for their results: the organiser finishes the event first.
  if exists (select 1 from public.tournaments t where t.organiser_id = me and t.status = 'in_progress') then
    raise exception 'tournament_running';
  end if;
  -- Files go through the Storage API (Supabase refuses SQL deletes there).
  if exists (select 1 from storage.objects o where o.owner = me) then
    raise exception 'files_left';
  end if;

  -- Other players' notices about me (they carry my name)
  delete from public.notifications n
   where n.user_id = me
      or n.payload ->> 'from_id' = me::text
      or n.payload ->> 'mentorship_id' in (select s.id::text from public.mentorships s where me in (s.mentor_id, s.mentee_id))
      or (n.payload ->> 'from' = my_name
          and (n.kind in ('game_deleted', 'suggestion')
               or n.payload ->> 'game_id' in (select p.game_id::text from public.game_players p where p.player_id = me
                                              union select g.id::text from public.games g where g.host_id = me)));
  -- From here on, the notices sent to other players (a cancelled game) carry no name.
  update public.profiles set display_name = 'Deleted player' where id = me;

  -- Games: the ones nobody else plays in, and the upcoming ones I host, disappear; I leave the others.
  for x in
    select g.id from public.games g
     where g.host_id = me
       and (g.starts_at > now()
            or (not exists (select 1 from public.game_players p
                             where p.game_id = g.id and p.player_id <> me and p.status = 'accepted')
                and not exists (select 1 from public.game_results r where r.game_id = g.id and r.player_id <> me)))
  loop
    perform public.delete_game(x.id);
  end loop;
  for x in
    select p.game_id from public.game_players p join public.games g on g.id = p.game_id
     where p.player_id = me and g.starts_at > now() and p.status in ('pending', 'accepted')
  loop
    perform public.leave_game(x.game_id);
  end loop;
  delete from public.game_players where player_id = me and status <> 'accepted';
  update public.game_players set message = null where player_id = me;
  delete from public.game_private where game_id in (select id from public.games where host_id = me);
  update public.games set note = null, area = null where host_id = me;
  update public.game_reports set summary = null where reported_by = me;
  -- My report photos are gone by now: drop their paths, keep the other players' photos.
  update public.game_reports r
     set photos = array(select f from unnest(r.photos) f
                         where exists (select 1 from storage.objects o where o.bucket_id = 'reports' and o.name = f))
   where cardinality(r.photos) > 0
     and exists (select 1 from public.game_players p where p.game_id = r.game_id and p.player_id = me);
  delete from public.game_messages where sender_id = me;
  delete from public.game_comments where author_id = me;

  -- Tournaments: drafts disappear, published ones are cancelled, finished ones stay.
  delete from public.tournaments where organiser_id = me and status = 'draft';
  update public.tournaments set status = 'cancelled', twitch_channel = null where organiser_id = me and status = 'published';
  for x in
    select r.tournament_id, t.status from public.registrations r join public.tournaments t on t.id = r.tournament_id
     where r.user_id = me and r.status in ('registered', 'waitlist') and t.status in ('published', 'in_progress')
  loop
    if x.status = 'published' then
      perform public.withdraw_from_tournament(x.tournament_id);
    else
      update public.registrations set status = 'dropped' where tournament_id = x.tournament_id and user_id = me;
    end if;
  end loop;
  delete from public.army_lists where registration_id in (select id from public.registrations where user_id = me);
  delete from public.contest_entries where user_id = me;
  delete from public.challenge_entries where user_id = me;
  delete from public.challenge_likes where user_id = me;
  delete from public.match_predictions where user_id = me;

  -- Leagues and campaigns: the oldest other member takes over, or they disappear with me.
  for x in select id from public.leagues where organiser_id = me loop
    select m.player_id into heir from public.league_members m
     where m.league_id = x.id and m.player_id <> me order by m.joined_at limit 1;
    if heir is null then
      delete from public.leagues where id = x.id;
    else
      update public.leagues set organiser_id = heir where id = x.id;
    end if;
  end loop;
  delete from public.league_members m using public.leagues l
   where l.id = m.league_id and m.player_id = me and l.ends_on >= current_date;
  for x in select id from public.campaigns where master_id = me loop
    select m.user_id into heir from public.campaign_members m
     where m.campaign_id = x.id and m.user_id <> me order by m.joined_at limit 1;
    if heir is null then
      delete from public.campaigns where id = x.id;
    else
      update public.campaigns set master_id = heir where id = x.id;
    end if;
  end loop;
  delete from public.campaign_decks where owner_id = me;
  delete from public.campaign_members where user_id = me;

  -- What is mine alone
  delete from public.decks where owner_id = me;
  delete from public.pile_armies where owner_id = me;
  delete from public.gallery_items where owner_id = me;
  delete from public.schemes where owner_id = me;
  delete from public.direct_messages where me in (sender_id, recipient_id);
  delete from public.mentorships where me in (mentor_id, mentee_id);
  delete from public.mentor_profiles where user_id = me;
  delete from public.lfg_posts where author_id = me;
  delete from public.swap_posts where user_id = me;
  delete from public.player_ratings where player_id = me;
  delete from public.active_days where user_id = me;
  delete from public.store_staff where user_id = me;
  delete from public.reports where reporter_id = me;
  delete from public.events where user_id = me;
  update public.bug_reports set user_id = null, contact = null, context = '{}', photos = '{}' where user_id = me;
  update public.suggestions set user_id = null, contact = null where user_id = me;
  update public.translation_suggestions set user_id = null where user_id = me;

  -- The name left on shared games and journals; suspended: an open session cannot post any more.
  update public.profiles
     set handle = 'deleted_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12),
         display_name = 'Deleted player', avatar_path = null, home_city = null, home_location = null,
         factions = '{}', preferred_lang = 'en', is_public = false,
         is_suspended = true, suspended_reason = null, deleted_at = now()
   where id = me;

  -- Sign-in data
  delete from auth.identities where user_id = me;
  delete from auth.sessions where user_id = me;
  delete from auth.one_time_tokens where user_id = me;
  delete from auth.mfa_factors where user_id = me;
  update auth.users
     set email = 'deleted-' || me::text || '@deleted.invalid', phone = null, encrypted_password = '',
         raw_user_meta_data = '{}', raw_app_meta_data = '{}', banned_until = now() + interval '100 years',
         confirmation_token = '', recovery_token = '', email_change = '', email_change_token_new = '',
         email_change_token_current = '', phone_change = '', phone_change_token = '', reauthentication_token = ''
   where id = me;
end;
$$;
revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

$setup_20261116000028_account_storage_fixes$;
    raise notice 'applied: 20261116000028_account_storage_fixes.sql';
  else
    raise notice 'already there, skipped: 20261116000028_account_storage_fixes.sql';
  end if;
end $guard$;
